// These bit values are exposed by history/budget/reason_bits. Keep existing
// assignments stable when adding reasons. Pressure and recovery reasons are
// separate: level 1 can persist after every instantaneous pressure has cleared.
const (
	historyLoadReasonHard historyLoadReason = 1 << iota
	historyLoadReasonNewStall
	historyLoadReasonDevicePressure
	historyLoadReasonL0Pressure
	historyLoadReasonDebtGrowth
	historyLoadReasonEngineUnavailable
	historyLoadReasonEngineStale
	historyLoadReasonRecoverySamples
	historyLoadReasonPressureHysteresis
	historyLoadReasonDeviceUnknown
)

var historyLoadReasonMetrics = [...]struct {

func (s *historyLoadState) cpuBurstReady(now time.Time) bool {
	p := s.sample
	return (s.level >= 2 || s.debtModerateReady(now)) && !s.hard && p.Available && freshHistoryLoad(p.SampledAt, now) &&
		!p.HardLimitReached(now) && p.DeviceAvailable && freshHistoryLoad(p.DeviceSampledAt, now) &&
		p.DeviceAwait >= 0 && p.DeviceAwait <= 2*time.Millisecond
}

	s.moderateL0.published = metrics.GetOrRegisterCounter(namespace+"moderate_l0/publications", nil)
	s.moderateL0.completed = metrics.GetOrRegisterCounter(namespace+"moderate_l0/completed", nil)
}

func (s *historyLoadState) moderateL0Evidence(now time.Time) bool {
	p := s.sample
	if s.hard || !p.Available || !freshHistoryLoad(p.SampledAt, now) || p.HardLimitReached(now) ||
		!p.DeviceAvailable || !freshHistoryLoad(p.DeviceSampledAt, now) || p.DeviceAwait < 0 || p.DeviceAwait > 2*time.Millisecond ||
		p.L0CompactionThreshold <= 0 || p.L0StopWritesThreshold <= 0 || p.L0Sublevels < 0 {
		return false
	}
	// Healthy points below T count too, so T-1/T oscillation cannot create a
	// second starvation boundary. Selection itself still requires L0>=T.
	return p.L0Sublevels < p.L0CompactionThreshold || p.L0Sublevels-p.L0CompactionThreshold < p.L0CompactionThreshold
}

func (s *historyLoadState) updateModerateL0(now time.Time, newSample, comparable, reset, newStall, devicePressure, severe bool) {
	m := &s.moderateL0
	p := s.sample
	sameThresholds := m.threshold == p.L0CompactionThreshold && m.stop == p.L0StopWritesThreshold
	if reset || newStall || devicePressure || severe || !s.moderateL0Evidence(now) {
		m.samples = 0
		return
	}
	if !sameThresholds {
		m.samples = 0
	}
	if newSample {
		if !comparable {
			m.samples = 0
		}
		m.threshold, m.stop = p.L0CompactionThreshold, p.L0StopWritesThreshold
		m.samples = min(2, m.samples+1)
	}
}

func (s *historyLoadState) moderateL0Ready(now time.Time) bool {
	return s.moderateL0.samples >= 2 && s.moderateL0Evidence(now) &&
		s.moderateL0.threshold == s.sample.L0CompactionThreshold && s.moderateL0.stop == s.sample.L0StopWritesThreshold &&
		s.sample.L0Sublevels >= s.sample.L0CompactionThreshold
}

func (s *historyLoadState) revokeExpiredModerateL0(now time.Time) {
	if !s.moderateL0Evidence(now) {
		s.moderateL0.samples = 0
		s.metric("moderate_l0_samples", 0)

func (r *Runner) busyHistoryAdmission(now time.Time) (ready, moderateL0 bool) {
	if !r.busyHistoryObservationEnabled() {
		return false, false
	}
	r.historyLoad.revokeExpiredModerateL0(now)
	burst, bounded := r.historyLoad.cpuBurstReady(now), r.historyLoad.moderateL0Ready(now)
	if !burst && !bounded {
		return false, false
	}
	resourceReady := r.cfg.BusyHistoryBuildReady()
	r.historyLoad.revokeExpiredModerateL0(time.Now())
	if !resourceReady {
		return false, false
	}
	// Preserve an already legal legacy opportunity, including its topology and
	// budget. The new lane only supplies capacity the old predicate denied.
	if burst {
		return true, false
	}
	// Only the independent bounded tier is new. Its callback must not carry
	// expired evidence into admission; the existing burst predicate is unchanged.
	bounded = bounded && r.historyLoad.moderateL0Ready(time.Now())

}
maxBusyDeferred := r.cfg.MaxBusyDeferredHistoryBlocks
if maxBusyDeferred < maxDeferred {
	maxBusyDeferred = maxDeferred
}
if r.cfg.SyncBuildReady != nil {
	result.HistoryAdmissionChecked = true
	result.HistoryAdmissionReady = r.cfg.SyncBuildReady()
	if !result.HistoryAdmissionReady {
		// Accelerated means an actually unthrottled ready build, not
		// merely a large lag candidate which a busy importer rejected.
		result.HistoryAccelerated = false
		if readyBlocks <= maxBusyDeferred && !pressured {
			result.HistoryBusyResourceReady, result.HistoryModerateL0 = r.busyHistoryAdmission(time.Now())
			if !result.HistoryBusyResourceReady {
				result.HistoryDeferred = true
				r.armBusyHistoryObservation(&result, time.Now())
				return result, nil
			}
		}
		// Both the liveness fallback and a resource opportunity use
		// bounded busy work. In particular, the latter must retain the
		// measured recovery instead of using ready acceleration or
		// falling back to the fixed ordinary build interval.
		result.HistoryForcedBusy = true
		// Above busy remains independently admitted even if this optional
		// tier is unavailable. Never turn that fallback into a wait.
		if !result.HistoryBusyResourceReady && r.historyLoad.moderateL0Ready(time.Now()) {
			_, result.HistoryModerateL0 = r.busyHistoryAdmission(time.Now())
		}
		result.HistoryDebtBlocks = readyBlocks
		result.HistoryDebtGrowth = coldSnapshotSignedDelta(readyBlocks, r.lastLagBlocks.Load())

func maxDeferredColdHistoryBlocks(historyWindow uint64) uint64 {
	const multiplier = uint64(4)
	if historyWindow > ^uint64(0)/multiplier {
		return ^uint64(0)
	}
	return historyWindow * multiplier
}

func maxBusyDeferredColdHistoryBlocks(maxDeferred uint64) uint64 {
	const multiplier = uint64(2)
	if maxDeferred > ^uint64(0)/multiplier {
		return ^uint64(0)
	}
	return maxDeferred * multiplier
}
